head.script:
scwin.cnt = 0;
scwin.trigger2_onclick = function(e) {
	var controlOptions = {
		minimize: true,
		maximize: true,
		close: true
	};
	if (scwin.cnt) {
		controlOptions = {
			minimize: false,
			maximize: false,
			close: false
		};
	}
	WebSquare.util.openPopup("/sample/common_link/p_popup_litewindow_WPF-1832_(WSQ-2938)_pop.xml", {
		id: "pop1",
		type: "litewindow",
		width: 500,
		height: 500,
		top: 50,
		left: 50,
		popupName: "test",
		modal: true,
		useIFrame: false,
		resizable: false,
		status: false,
		menubar: false,
		scrollbars: false,
		title: "test222",
		useMaxmimize: true,
		useControl: true,
		controls: controlOptions,
		foldSize: {
			width: 200
		},
		foldOnMinimized: true
	});
	scwin.cnt++;
};
scwin.__isHidden = function() {
	var ctl = document.getElementById("pop1_header_control") || document.getElementById("mf_pop1_header_control");
	var divs = ctl ? ctl.getElementsByTagName("div") : [];
	var count = 0;
	for (var k = 0; k < divs.length; k++) {
		if (getComputedStyle(divs[k]).display == "none") {
			count++;
		}
	}
	return count == divs.length;
};
